        "평가사유": "[화제성 8점] (확정 →) 국립중앙박물관 공식 '예정 전시'에 2026-11-27~2027-04-18, 특별전시실1로 등재. 쿤스트하우스 취리히는 유럽 근대미술 명품 소장처로, 국립중앙박물관이 2026년 기조로 밝힌 '굵직한 국제 전시' 라인 중 하나다. 국립중앙박물관 유료 특별전은 통상 수십만 관객을 동원한다. (추정 →) 출품작 리스트·관람료는 미공개라 정확한 동원 규모는 예측 단계다. [독창성 5점] (독점성·희소성·차별 기획 관점) 취리히 컬렉션의 국내 대규모 첫 소개라는 희소성은 분명하다. 다만 공개 전시이고 독점 취재권이 없어 실무자 캘리브레이션 원칙 1에 따라 상단을 열어주지 않았다. [근접성 8점] (수도권/지방·기간·관객 친숙도) 서울 용산 국립중앙박물관, 5개월 장기 개최. 접근성·체류기간 모두 최상위. 인상파·근대미술은 국내 관객 친숙도가 높은 소재다. [영향성 8점] 미술사 기획전은 우리 매체가 지속적으로 다뤄온 영역이라 신뢰도 제고에 기여한다(캘리브레이션 원칙 4). 5개월 장기라 연계 콘텐츠 제작·재노출 창구가 넓다. [종합] 강점: 이번 윈도우 전시 최대어, 장기 개최, 매체 정체성 정합. 약점·리스크: 출품작·관람료·주요 작가 라인업이 아직 미공개여서 기획 확정 전 재확인 필요. 편성 관점: 12-18 개막 《마리 앙투아네트 스타일》(같은 박물관 특별전시실2)과 묶어 '국립중앙박물관 겨울 2대 특별전' 기획으로 확장 가능.",
